/* Pen Pen port, S3: what the recompiled C (generated by recomp.py into the penpen-build volume) expects
 * from the run time. The same generated files build the boot runtime and the differential harness
 * (-DRT_DIFF: every call, direct or not, goes through rt_call so the harness can stub it). */
#ifndef RT_GEN_H
#define RT_GEN_H

#include "../sh4/sh4_ops.h"

typedef void (*rt_fn)(SH4 *);
typedef struct { uint32_t addr; rt_fn fn; } rt_fn_entry;
extern const rt_fn_entry rt_fn_table[]; /* sorted by address */
extern const int rt_fn_count;

#define RT_NORM(a) ((((uint32_t)(a)) & 0x1FFFFFFFu) | 0x80000000u)

/* Call guest code at a (any alias): HLE stub, translated function or interpreter. On return c->pc holds
 * the address the callee returned to (its rts target). */
void rt_call(SH4 *c, uint32_t a);
rt_fn rt_lookup(uint32_t a);
__attribute__((noreturn)) void rt_illegal(SH4 *c, uint32_t a);
__attribute__((noreturn)) void rt_illegal_slot(SH4 *c, uint32_t a);
__attribute__((noreturn)) void rt_unsupported(SH4 *c, uint32_t a);
void rt_badret(SH4 *c, uint32_t want, uint32_t at);
void rt_budget(SH4 *c, uint32_t at);

#define CALL_I(t, ret, at) do { rt_call(c, (t)); if (c->pc != (ret)) rt_badret(c, (ret), (at)); } while (0)
#ifdef RT_DIFF
#define CALL_D(fn, k, ret, at) CALL_I(k, ret, at)
#define TAIL_D(fn, k) rt_call(c, (k))
#else
#define CALL_D(fn, k, ret, at) do { fn(c); if (c->pc != (ret)) rt_badret(c, (ret), (at)); } while (0)
#define TAIL_D(fn, k) fn(c)
#endif
/* every backward branch: the harness's step budget, the runtime's watchdog for polling loops */
#define BACK(at) do { if (--c->budget < 0) rt_budget(c, (at)); } while (0)

#endif
